import{_ as l,C as a,o as g,c as i,a5 as n,E as r,j as e,a as s}from"./chunks/framework.DuVjalqf.js";const c="/rb_cobot_docs_muscat/images/program/user-input-form.avif",h="/rb_cobot_docs_muscat/images/program/user-select-form.avif",f=JSON.parse('{"title":"사용자 입력","description":"","frontmatter":{"title":"사용자 입력","outline":[2,3]},"headers":[],"relativePath":"manual/program/user-input.md","filePath":"manual/program/user-input.md","lastUpdated":1792552919000}'),p={name:"manual/program/user-input.md"};function u(b,t,m,_,x,q){const o=a("DemoFrame"),d=a("ScenarioSteps");return g(),i("div",null,[t[0]||(t[0]=n('<h1 id="사용자-입력" tabindex="-1">사용자 입력 <a class="header-anchor" href="#사용자-입력" aria-label="Permalink to &quot;사용자 입력&quot;">​</a></h1><p><strong>사용자 입력</strong>은 프로그램을 실행하는 도중 사용자에게 값을 묻고 답을 받아 이어서 실행하는 명령입니다. 작업자가 현장에서 값을 확인하거나 다음 동작을 직접 고르게 하고 싶을 때 사용합니다. 명령은 두 가지 동작 중 하나로 설정합니다.</p><table tabindex="0"><thead><tr><th>동작</th><th>하는 일</th></tr></thead><tbody><tr><td><strong>사용자 입력</strong></td><td>선언해 둔 변수의 값을 사용자가 입력하게 합니다. 실행 중 변수 이름과 현재 값이 표시된 창이 나타나고, 사용자가 값을 입력하면 이어서 진행합니다.</td></tr><tr><td><strong>사용자 선택</strong></td><td>질문과 선택지를 보여 주고 사용자가 고른 선택지의 번호(0부터)를 변수에 저장합니다.</td></tr></tbody></table><p>이 문서에서는 <strong>프로그램</strong> 화면에서 다음을 해 봅니다.</p><ul><li>사용자 입력 명령을 추가하고 입력받을 변수 정하기</li><li>같은 명령을 사용자 선택으로 바꾸고 질문·선택지 정하기</li></ul><div class="tip custom-block"><p class="custom-block-title">준비</p><p>프로그램이 하나 열려 있어야 합니다(<a href="/rb_cobot_docs_muscat/manual/program-create">새 프로그램 만들기</a>). 사용자 입력 동작은 <strong>변수선언</strong>으로 먼저 선언한 변수가 있어야 고를 수 있습니다.</p></div><h2 id="사용자-입력-동작" tabindex="-1">사용자 입력 동작 <a class="header-anchor" href="#사용자-입력-동작" aria-label="Permalink to &quot;사용자 입력 동작&quot;">​</a></h2><p>설정 화면의 <strong>옵션</strong>에서 사용자 입력을 고른 화면입니다. 앞에서 선언한 변수 <code>user_name</code>(STRING)이 있는 프로그램입니다.</p><p><img src="'+c+'" alt="사용자 입력 설정 화면"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">①</td><td><strong>옵션</strong></td><td>사용자 입력과 사용자 선택 중 동작을 고릅니다.</td></tr><tr><td style="text-align:center;">②</td><td><strong>변수 유형</strong></td><td>입력받을 변수의 유형입니다. STRING, NUMERIC, BOOLEAN, LIST, DICTIONARY, VARIABLE 중에서 고르며, 유형을 바꾸면 ③이 그 유형의 변수 목록으로 바뀝니다.</td></tr><tr><td style="text-align:center;">③</td><td><strong>변수 선택</strong></td><td>입력받을 변수입니다. 이 명령보다 <strong>앞에서 선언한 변수</strong> 중 ②에서 고른 유형의 변수만 나타납니다. 고를 수 있는 변수가 없으면 &quot;변수를 선택해주세요.&quot;라고 표시되고 저장할 수 없습니다.</td></tr><tr><td style="text-align:center;">④</td><td><strong>닫기</strong></td><td>설정 화면을 닫습니다. 저장하지 않은 변경이 있으면 저장하지 않고 닫을지 묻습니다.</td></tr><tr><td style="text-align:center;">⑤</td><td><strong>저장</strong></td><td>설정을 적용합니다. 트리의 사용자 입력 옆에 <code>STRING: user_name</code>처럼 유형과 변수 이름이 표시됩니다.</td></tr></tbody></table></div><p>프로그램을 실행해 이 명령에 이르면 프로그램이 멈추고 변수 이름과 현재 값이 표시된 창이 나타납니다. 사용자가 값을 입력해 확인하면 이어서 진행합니다.</p><h2 id="사용자-선택-동작" tabindex="-1">사용자 선택 동작 <a class="header-anchor" href="#사용자-선택-동작" aria-label="Permalink to &quot;사용자 선택 동작&quot;">​</a></h2><p>옵션에서 <strong>사용자 선택</strong>을 고르면 설정 화면이 팝업 설정과 선택지로 바뀝니다.</p><p><img src="'+h+'" alt="사용자 선택 설정 화면"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">①</td><td><strong>질문 메시지</strong></td><td>사용자에게 보여 줄 질문입니다. 비워 두면 저장할 수 없습니다.</td></tr><tr><td style="text-align:center;">②</td><td><strong>선택한 번호를 저장할 변수 이름</strong></td><td>사용자가 고른 선택지의 번호를 저장할 변수 이름입니다. 비워 두면 저장할 수 없습니다.</td></tr><tr><td style="text-align:center;">③</td><td><strong>선택 지연시간 (초)</strong></td><td>선택을 기다리는 시간입니다. 기본값은 60입니다.</td></tr><tr><td style="text-align:center;">④</td><td><strong>타임아웃이 발생했을 때 선택할 번호</strong></td><td>타임아웃이 발생했을 때 선택할 선택지 번호입니다. 기본값은 0입니다.</td></tr><tr><td style="text-align:center;">⑤</td><td><strong>선택지</strong></td><td>사용자에게 보여 줄 선택지 목록입니다. 기본으로 0번 <code>No</code>, 1번 <code>Yes</code> 두 개가 있으며, 문구를 바꿀 수 있습니다. 앞의 숫자가 변수에 저장되는 번호입니다.</td></tr><tr><td style="text-align:center;">⑥</td><td><strong>선택지 추가</strong></td><td>선택지를 한 줄 더합니다. 최대 20개까지 추가할 수 있습니다. 목록 아래의 <strong>선택지 추가</strong> 버튼도 같은 동작입니다.</td></tr><tr><td style="text-align:center;">⑦</td><td><strong>닫기</strong></td><td>설정 화면을 닫습니다.</td></tr><tr><td style="text-align:center;">⑧</td><td><strong>저장</strong></td><td>설정을 적용합니다. 트리의 명령 이름이 <strong>사용자 선택</strong>으로 바뀌고 질문 메시지가 옆에 표시됩니다.</td></tr></tbody></table></div><p>선택지는 0번과 1번을 지울 수 없고, 2번부터는 줄 오른쪽의 삭제 버튼으로 지울 수 있습니다. 입력칸을 누르면 화면 키보드가 나타나며, 키보드의 <strong>Close</strong>로 닫습니다.</p><h2 id="프로그램을-실행하면" tabindex="-1">프로그램을 실행하면 <a class="header-anchor" href="#프로그램을-실행하면" aria-label="Permalink to &quot;프로그램을 실행하면&quot;">​</a></h2><p>프로그램이 사용자 입력·사용자 선택에 이르면 <strong>프로그램이 멈추고 창이 나타납니다.</strong> 사용자가 응답하면 이어서 실행합니다.</p><h3 id="사용자-입력-창" tabindex="-1">사용자 입력 창 <a class="header-anchor" href="#사용자-입력-창" aria-label="Permalink to &quot;사용자 입력 창&quot;">​</a></h3><p><strong>사용자 변수 값 변경</strong> 창이 나타나며 <strong>변수 유형</strong>과 <strong>변수</strong>(변수 이름과 현재 값), 새 값을 적는 <strong>적용할 값</strong>, 유형별 <strong>입력 예시</strong>가 표시됩니다.</p><table tabindex="0"><thead><tr><th>버튼</th><th>하는 일</th></tr></thead><tbody><tr><td><strong>반영 후 계속</strong></td><td>입력한 값을 변수에 적용하고 이어서 실행합니다.</td></tr><tr><td><strong>스킵</strong></td><td>값을 바꾸지 않고 이어서 실행합니다.</td></tr><tr><td><strong>프로그램 정지</strong></td><td>프로그램을 멈춥니다.</td></tr></tbody></table><p>적용할 값은 변수 유형에 맞게 적어야 합니다. 맞지 않으면 반영되지 않습니다.</p><table tabindex="0"><thead><tr><th>변수 유형</th><th>적는 방법</th></tr></thead><tbody><tr><td>STRING</td><td>큰따옴표로 감쌉니다. 예: <code>&quot;Robot_Mode_1&quot;</code></td></tr><tr><td>NUMERIC</td><td>정수나 실수입니다. 예: <code>100</code>, <code>3.14</code>, <code>-45.5</code></td></tr><tr><td>BOOLEAN</td><td><code>True</code> 또는 <code>False</code></td></tr><tr><td>LIST</td><td>대괄호로 감쌉니다. 예: <code>[0, -90, 90, -90, -90, 0, 0]</code></td></tr><tr><td>DICTIONARY</td><td>중괄호로 감쌉니다. 예: <code>{&quot;tool_name&quot;: &quot;Gripper_A&quot;}</code></td></tr></tbody></table><h3 id="사용자-선택-창" tabindex="-1">사용자 선택 창 <a class="header-anchor" href="#사용자-선택-창" aria-label="Permalink to &quot;사용자 선택 창&quot;">​</a></h3><p>질문 메시지가 <strong>창 제목</strong>이 되고, 선택지가 <code>0: No</code>, <code>1: Yes</code>처럼 <strong>번호와 함께 버튼</strong>으로 나타납니다. 선택지를 누르면 그 <strong>번호</strong>가 지정한 변수에 저장되고 프로그램이 이어서 실행됩니다.</p><table tabindex="0"><thead><tr><th>버튼</th><th>하는 일</th></tr></thead><tbody><tr><td><strong>선택지 버튼</strong></td><td>그 번호를 변수에 저장하고 이어서 실행합니다.</td></tr><tr><td><strong>스킵</strong></td><td>고르지 않고 이어서 실행합니다. 변수 값은 바뀌지 않습니다.</td></tr><tr><td><strong>프로그램 정지</strong></td><td>프로그램을 멈춥니다.</td></tr></tbody></table><p>선택 지연시간(초) 안에 고르지 않으면 <strong>타임아웃이 발생했을 때 선택할 번호</strong>의 선택지가 골라진 것으로 처리됩니다.</p><h2 id="직접-해-보기" tabindex="-1">직접 해 보기 <a class="header-anchor" href="#직접-해-보기" aria-label="Permalink to &quot;직접 해 보기&quot;">​</a></h2><p>예제 프로그램은 문자열 변수 <code>user_name</code>과 숫자 변수 <code>answer</code>를 선언하고, 끝의 디버그가 두 값을 보여 줍니다. 실습은 두 가지이며 어느 쪽부터 해도 되고, 앞의 실습을 하지 않아도 시작할 수 있습니다. 실습을 다시 시작하면 바꾼 값은 처음 상태로 돌아갑니다.</p><h3 id="사용자-입력-만들기" tabindex="-1">사용자 입력 만들기 <a class="header-anchor" href="#사용자-입력-만들기" aria-label="Permalink to &quot;사용자 입력 만들기&quot;">​</a></h3><p>가운데 빈 영역에 사용자 입력을 넣고 실행해 입력한 값이 변수에 적용되는 것을 확인하는 과정입니다.</p><ol><li>빈 영역에 <strong>사용자 입력</strong>을 추가하고 설정 화면에서 변수 유형(STRING)과 변수(<code>user_name</code>)를 확인한 뒤 저장합니다.</li><li>재생(▶)을 누르고 <strong>프로그램 변경 확인</strong> 창에서 <strong>저장</strong>을 누르면 <strong>사용자 변수 값 변경</strong> 창이 나타납니다. <strong>적용할 값</strong>에 정해진 값 <code>&quot;Robot_A&quot;</code>를 큰따옴표까지 포함해 입력합니다. 입력한 값이 정해진 값과 같아야 다음으로 넘어갈 수 있으며, 공백은 다르게 입력해도 같은 값으로 봅니다. 건너뛰면 자동으로 입력됩니다.</li><li><strong>반영 후 계속</strong>을 누르면 디버그 창에 <code>user_name: &quot;Robot_A&quot;</code>가 표시됩니다. 문자열은 디버그 창에서 큰따옴표로 감싸 표시되고, 아직 바꾸지 않은 <code>answer</code>는 <code>0.0</code>입니다.</li></ol>',32)),r(o,{id:"program-user-input-input"}),t[1]||(t[1]=e("h4",{id:"사용-방법",tabindex:"-1"},[s("사용 방법 "),e("a",{class:"header-anchor",href:"#사용-방법","aria-label":'Permalink to "사용 방법"'},"​")],-1)),r(d,{id:"program-user-input-input"}),t[2]||(t[2]=n('<h3 id="사용자-선택으로-바꾸기" tabindex="-1">사용자 선택으로 바꾸기 <a class="header-anchor" href="#사용자-선택으로-바꾸기" aria-label="Permalink to &quot;사용자 선택으로 바꾸기&quot;">​</a></h3><p>사용자 입력이 들어 있는 프로그램에서 그 명령을 사용자 선택으로 바꿔 실행하는 과정입니다.</p><ol><li>트리의 사용자 입력 설정 화면을 열어 사용자 선택으로 바꿉니다. 질문 메시지에 <code>Continue?</code>, 선택한 번호를 저장할 변수 이름에 <code>answer</code>를 입력하고 저장합니다.</li><li>재생(▶)을 누르고 <strong>프로그램 변경 확인</strong> 창에서 <strong>저장</strong>을 누르면 질문과 선택지가 있는 창이 나타납니다. <code>1: Yes</code>를 누르면 디버그 창에 <code>answer: 1.0</code>이 표시됩니다.</li></ol>',3)),r(o,{id:"program-user-input-select"}),t[3]||(t[3]=e("h4",{id:"사용-방법-1",tabindex:"-1"},[s("사용 방법 "),e("a",{class:"header-anchor",href:"#사용-방법-1","aria-label":'Permalink to "사용 방법"'},"​")],-1)),r(d,{id:"program-user-input-select"})])}const T=l(p,[["render",u]]);export{f as __pageData,T as default};
